// @ohos/dsh-ptc-runtime-vm — in-process PTC runtime for HarmonyOS.
//
// Registers `ctx.ptcRuntime` for the `ohos` profile as a drop-in replacement
// for @deepseek-ai/dsh-ptc-runtime-node, whose child-process substrate can
// never run here (fork/exec is forbidden on HarmonyOS). Model-written
// `run_code` programs are evaluated inside a fresh `node:vm` context hosted
// by a worker_thread of this same process:
//
//   - the vm context exposes ONLY the declared binding namespaces (e.g.
//     `tools`), their rejection classes, a capturing `console`, and the
//     ECMAScript intrinsics — no `require`, no `process`, no Node APIs;
//   - binding calls bridge back to the main thread as messages and execute
//     the host functions dsh-tools supplied, so every tool policy
//     (containment, three-tier permissions, approvals) applies unchanged;
//   - the elapsed-time budget is enforced from the main thread with
//     `worker.terminate()`, which also breaks synchronous infinite loops —
//     the property a bare vm context cannot give;
//   - no file confinement is claimed (`sandboxMode` stays undefined), so
//     dsh-tools never attaches a sandbox policy and rejects model requests
//     for sandbox escalation cleanly.
//
// TypeScript note: dsh's other TypeScript backend relies on Node's native
// type stripping, which is WASM-backed (amaro) and therefore unavailable
// under `--jitless`. This runtime declares `language: "typescript"` (the SDK
// section and run_code flavor key off it) but instructs the model, via
// `executionInstructions`, to write plain ECMAScript — annotations are NOT
// stripped here and are syntax errors. See docs/GAP-ANALYSIS.md.

import { Buffer } from "node:buffer";
import { isAbsolute } from "node:path";
import {
	DUNDER_MEMBER,
	PORTABLE_RESERVED_WORDS,
	PtcRuntime,
	RESERVED_BINDING_GLOBALS,
	RESERVED_ERROR_MEMBERS
} from "@deepseek-ai/dsh-ptc-runtime";
import z from "@deepseek-ai/schemastery";

const WORKER_URL = new URL("./worker.js", import.meta.url);

const IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;
const FAILURE_KINDS = new Set([
	"exception",
	"timeout",
	"abort",
	"worker-exit",
	"invalid-output",
	"output-limit",
	"protocol",
	"sandbox-unavailable"
]);

/** Loader config for this provider; defaults mirror dsh-ptc-runtime-node where device-appropriate. */
export const Config = z.object({
	/** Default elapsed budget per run when the caller supplies none. */
	timeoutMs: z.number().default(12e4),
	/** Hard cap on any per-run elapsed budget. */
	maxTimeoutMs: z.number().default(6e5),
	/** Cap on the serialized outer output (logs + completion value) of one run. */
	maxOutputBytes: z.number().default(1048576),
	/** Per-worker old-generation heap limit, when the build supports resourceLimits. */
	maxOldGenerationSizeMb: z.number().default(256)
});

const DEFAULTS = {
	timeoutMs: 12e4,
	maxTimeoutMs: 6e5,
	maxOutputBytes: 1048576,
	maxOldGenerationSizeMb: 256
};

/** Merge loader config over defaults and validate every field. @internal exported for tests. */
export function normalizeConfig(config) {
	const merged = { ...DEFAULTS, ...config };
	for (const [key, value] of Object.entries(merged)) {
		if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
			throw new Error(`ptc-runtime-vm: ${key} must be positive and finite`);
		}
	}
	if (!Number.isSafeInteger(merged.maxOutputBytes) || merged.maxOutputBytes < 4) {
		throw new Error("ptc-runtime-vm: maxOutputBytes must be an integer of at least 4");
	}
	if (!Number.isSafeInteger(merged.maxOldGenerationSizeMb)) {
		throw new Error("ptc-runtime-vm: maxOldGenerationSizeMb must be an integer");
	}
	if (merged.timeoutMs > merged.maxTimeoutMs) {
		throw new Error("ptc-runtime-vm: timeoutMs must not exceed maxTimeoutMs");
	}
	return merged;
}

/** Lossless-JSON check shared with worker.js (duplicated on purpose — see worker header). */
export function jsonViolation(value, label) {
	if (value === null) return null;
	const kind = typeof value;
	if (kind === "boolean") return null;
	if (kind === "number") {
		if (!Number.isFinite(value)) return `${label}: non-finite number`;
		return null;
	}
	if (kind === "string") return null;
	if (kind === "object") {
		if (Array.isArray(value)) {
			for (let index = 0; index < value.length; index += 1) {
				const violation = jsonViolation(value[index], `${label}[${index}]`);
				if (violation !== null) return violation;
			}
			return null;
		}
		for (const key of Object.keys(value)) {
			const violation = jsonViolation(value[key], `${label}.${key}`);
			if (violation !== null) return violation;
		}
		return null;
	}
	return `${label}: ${kind} is not a JSON value`;
}

function messageOf(error) {
	if (error instanceof Error) return error.message;
	if (error !== null && typeof error === "object" && typeof error.message === "string") return error.message;
	return String(error);
}

function reasonText(reason) {
	if (reason === undefined) return "cancelled";
	return String(reason);
}

/**
 * Validate one run's binding namespaces against the portable contract
 * (dsh-ptc-runtime): identifier-shaped globals outside every reserved set,
 * function-valued members, and rejection-class names/members outside their
 * own reserved sets. Runs before anything is posted to the worker, so the
 * data-driven setup there never receives an unexpected shape.
 */
export function validateBindings(spec) {
	if (typeof spec.program !== "string") throw new Error("ptc-runtime-vm: program must be a string");
	if (!Array.isArray(spec.bindings) || spec.bindings.length === 0) {
		throw new Error("ptc-runtime-vm: bindings must be a non-empty array");
	}
	const globals = new Set();
	for (const namespace of spec.bindings) {
		const global = namespace?.global;
		if (typeof global !== "string" || !IDENTIFIER.test(global) || PORTABLE_RESERVED_WORDS.has(global) || RESERVED_BINDING_GLOBALS.has(global)) {
			throw new Error(`ptc-runtime-vm: invalid binding global ${JSON.stringify(global)}`);
		}
		if (globals.has(global)) throw new Error(`ptc-runtime-vm: duplicate binding global ${JSON.stringify(global)}`);
		globals.add(global);
		const functions = namespace?.functions;
		if (functions === null || typeof functions !== "object" || Array.isArray(functions)) {
			throw new Error(`ptc-runtime-vm: binding ${global}.functions must be an object`);
		}
		for (const [name, value] of Object.entries(functions)) {
			if (typeof value !== "function") throw new Error(`ptc-runtime-vm: binding ${global}.${name} must be a function`);
		}
		const errorClass = namespace.errorClass;
		if (errorClass !== undefined && errorClass !== null) {
			const name = errorClass?.name;
			if (typeof name !== "string" || !IDENTIFIER.test(name) || PORTABLE_RESERVED_WORDS.has(name) || RESERVED_BINDING_GLOBALS.has(name)) {
				throw new Error(`ptc-runtime-vm: invalid error class name ${JSON.stringify(name)}`);
			}
			const member = errorClass?.memberNameProperty;
			if (typeof member !== "string" || member.length === 0 || RESERVED_ERROR_MEMBERS.has(member) || DUNDER_MEMBER.test(member)) {
				throw new Error(`ptc-runtime-vm: invalid error member name ${JSON.stringify(member)}`);
			}
		}
	}
}

/** Clamp a requested elapsed budget: default → configured default; explicit → capped at max; null → no deadline. */
export function clampTimeoutMs(requested, config) {
	if (requested === undefined) return config.timeoutMs;
	if (requested === null) return null;
	if (!Number.isFinite(requested) || requested <= 0) throw new Error("ptc-runtime-vm: timeoutMs must be a positive finite number or null");
	return Math.min(requested, config.maxTimeoutMs);
}

let workerModulePromise;
function loadWorkerModule() {
	workerModulePromise ??= import("node:worker_threads").then(
		(module) => module,
		() => null
	);
	return workerModulePromise;
}

function postResult(worker, id, settle) {
	try {
		worker.postMessage({ t: "result", id, settle });
	} catch {
		// The worker was already terminated; the program is gone with it.
	}
}

/**
 * Start one run and return its handles. `result` is the PtcRunResult promise,
 * `abort(reason)` settles it with a kind:'abort' failure, and `finished`
 * resolves once the worker (if any) is fully terminated. Neither rejects.
 */
export function startRun(spec, config) {
	validateBindings(spec);
	let settled = false;
	const logs = [];
	let ledgerBytes = 0;
	const done = Promise.withResolvers();
	const exited = Promise.withResolvers();
	let timer;
	let abortListener;
	let workerRef;

	const finish = (partial) => {
		if (settled) return;
		settled = true;
		if (timer !== undefined) clearTimeout(timer);
		if (abortListener !== undefined) spec.signal?.removeEventListener("abort", abortListener);
		done.resolve({ logs, ...partial });
		const worker = workerRef;
		if (worker === undefined) {
			exited.resolve();
		} else {
			worker.terminate().then(() => exited.resolve(), () => exited.resolve());
		}
	};

	if (spec.signal?.aborted) {
		finish({ error: { kind: "abort", message: `aborted: ${reasonText(spec.signal.reason)}` } });
		return { result: done.promise, abort: () => {}, finished: exited.promise };
	}

	const effectiveTimeoutMs = spec.timeoutMs === undefined ? config.timeoutMs : spec.timeoutMs;

	loadWorkerModule().then((module) => {
		if (settled) return;
		if (module === null) {
			finish({ error: { kind: "worker-exit", message: "worker_threads is unavailable in this build — no in-process execution substrate for run_code" } });
			return;
		}
		let worker;
		try {
			try {
				worker = new module.Worker(WORKER_URL, { resourceLimits: { maxOldGenerationSizeMb: config.maxOldGenerationSizeMb } });
			} catch {
				worker = new module.Worker(WORKER_URL);
			}
		} catch (error) {
			finish({ error: { kind: "worker-exit", message: `worker substrate failed to start: ${messageOf(error)}` } });
			return;
		}
		workerRef = worker;

		const overCap = (what) => finish({ error: { kind: "output-limit", message: `serialized output exceeded the ${config.maxOutputBytes}-byte cap (${what}); emit less` } });

		worker.on("message", (message) => {
			if (settled || message === null || typeof message !== "object") return;
			if (message.t === "log") {
				const text = typeof message.text === "string" ? message.text : String(message.text);
				ledgerBytes += Buffer.byteLength(text, "utf8");
				if (ledgerBytes > config.maxOutputBytes) {
					overCap("captured console output");
					return;
				}
				logs.push(text);
				return;
			}
			if (message.t === "call") {
				if (typeof message.id !== "number" || typeof message.ns !== "string" || typeof message.name !== "string") return;
				const namespace = spec.bindings.find((candidate) => candidate.global === message.ns);
				const fn = namespace?.functions?.[message.name];
				if (fn === undefined) {
					postResult(worker, message.id, { isError: true, message: `unknown binding ${message.ns}.${message.name}` });
					return;
				}
				const violation = jsonViolation(message.args, `${message.ns}.${message.name} args`);
				if (violation !== null) {
					postResult(worker, message.id, { isError: true, message: violation });
					return;
				}
			Promise.resolve()
				.then(() => fn(message.args))
				.then(
					(value) => {
						// dsh-tools' binding contract: resolve = the tool's JSON value
						// (possibly undefined for void tools), reject = the failure.
						if (value !== undefined) {
							const valueViolation = jsonViolation(value, `${message.ns}.${message.name} result`);
							if (valueViolation !== null) {
								postResult(worker, message.id, { isError: true, message: `tool result is not lossless JSON: ${valueViolation}` });
								return;
							}
						}
						postResult(worker, message.id, { isError: false, value });
					},
					(error) => postResult(worker, message.id, { isError: true, message: messageOf(error) })
				);
				return;
			}
			if (message.t === "done") {
				if (message.ok) {
					if (message.value !== undefined) {
						const violation = jsonViolation(message.value, "program result");
						if (violation !== null) {
							finish({ error: { kind: "invalid-output", message: `${violation} — return lossless JSON, or console.log a rendering instead` } });
							return;
						}
						const serialized = JSON.stringify(message.value);
						ledgerBytes += serialized === undefined ? config.maxOutputBytes + 1 : Buffer.byteLength(serialized, "utf8");
						if (ledgerBytes > config.maxOutputBytes) {
							overCap("completion value");
							return;
						}
					}
					finish(message.value === undefined ? {} : { value: message.value });
				} else {
					const failure = message.error;
					const kind = FAILURE_KINDS.has(failure?.kind) ? failure.kind : "exception";
					finish({ error: { kind, message: typeof failure?.message === "string" ? failure.message : "program failed" } });
				}
			}
		});
		worker.on("error", (error) => finish({ error: { kind: "worker-exit", message: messageOf(error) } }));
		worker.on("messageerror", (error) => finish({ error: { kind: "protocol", message: messageOf(error) } }));
		worker.on("exit", (code) => {
			if (!settled) finish({ error: { kind: "worker-exit", message: `worker exited before settling (code ${code})` } });
			exited.resolve();
		});

		if (effectiveTimeoutMs !== null) {
			timer = setTimeout(() => {
				finish({ error: { kind: "timeout", message: `elapsed budget of ${effectiveTimeoutMs}ms exceeded; the program was killed` } });
			}, effectiveTimeoutMs);
		}
		abortListener = () => finish({ error: { kind: "abort", message: `aborted: ${spec.signal === undefined ? "" : reasonText(spec.signal.reason)}`.trim() } });
		spec.signal?.addEventListener("abort", abortListener, { once: true });

		worker.postMessage({
			t: "run",
			program: spec.program,
			namespaces: spec.bindings.map((namespace) => ({
				global: namespace.global,
				names: Object.keys(namespace.functions),
				errorClass: namespace.errorClass === undefined ? null : namespace.errorClass
			}))
		});
	});

	return {
		result: done.promise,
		abort: (reason) => finish({ error: { kind: "abort", message: `aborted: ${reasonText(reason)}` } }),
		finished: exited.promise
	};
}

/** Await one run to completion (helper for tests and non-cancelling callers). */
export async function runInWorker(spec, config) {
	const run = startRun(spec, config);
	await run.finished;
	return run.result;
}

/**
 * The in-process PTC runtime service for the `ohos` profile.
 */
export class OhosPtcRuntime extends PtcRuntime {
	static inject = [];
	static Config = Config;
	language = "typescript";
	config;
	// Plain property, NOT a #private field: cordis traceable shadows invoke
	// service methods with `this` = a Proxy over the instance, and V8 brand
	// checks for private fields fail on that receiver.
	activeRuns = new Set();

	constructor(ctx, config) {
		super(ctx);
		this.config = normalizeConfig(config ?? {});
		ctx.effect(() => async () => {
			const live = [...this.activeRuns];
			this.activeRuns.clear();
			for (const run of live) run.abort("runtime disposed");
			await Promise.all(live.map((run) => run.finished));
		}, "ptc-runtime-vm cleanup");
	}

	get timeout() {
		return {
			defaultMs: Math.min(this.config.timeoutMs, this.config.maxTimeoutMs),
			maxMs: this.config.maxTimeoutMs
		};
	}

	get executionInstructions() {
		return `The program is the body of an async function; top-level await and return are supported. Write plain ECMAScript only: this backend does not run TypeScript type-stripping, so type annotations, interface/type declarations and as-casts are syntax errors — write plain JavaScript and never copy the declare/interface blocks below into the program. Emit output with console.log(...) or return a lossless JSON value; only printed and returned values become program output. Only the tools binding is available: no Node APIs, no filesystem, no process/env access, no timers — orchestrate tools instead. Each call runs in a fresh, stateless environment. A run is killed when its elapsed budget expires (default ${this.timeout.defaultMs}ms, capped at ${this.timeout.maxMs}ms).`;
	}

	resolve(request) {
		if (request.sandboxPolicy !== undefined) {
			throw new Error("ptc-runtime-vm: this provider has no file confinement — sandboxPolicy is not accepted");
		}
		validateBindings(request);
		if (request.cwd !== undefined && !isAbsolute(request.cwd)) {
			throw new Error("ptc-runtime-vm: cwd must be absolute");
		}
		return {
			...request,
			cwd: request.cwd ?? process.cwd(),
			timeoutMs: clampTimeoutMs(request.timeoutMs, this.config)
		};
	}

	async run(spec) {
		const live = startRun(spec, this.config);
		this.activeRuns.add(live);
		try {
			return await live.result;
		} finally {
			this.activeRuns.delete(live);
			await live.finished;
		}
	}
}

export default OhosPtcRuntime;
